import { test } from 'node:test';
import assert from 'node:assert/strict';
import { scriptedModel } from './helpers/mock-model.js';
import { triageTicket } from '../src/triage.js';

test('triageTicket returns a valid triage object', async () => {
  const model = scriptedModel([
    {
      toolCalls: [{ name: 'getCustomer', input: { customerId: 'C1' } }],
      usage: [100, 7],
    },
    {
      text: JSON.stringify({
        category: 'billing',
        priority: 'high',
        reply: 'Thank you for reaching out. We are looking into your billing issue.',
      }),
      usage: [200, 9],
    },
  ]);

  const result = await triageTicket(model, {
    customerId: 'C1',
    text: 'I was charged twice for my subscription',
  });

  assert.equal(result.category, 'billing');
  assert.equal(result.priority, 'high');
  assert.equal(typeof result.reply, 'string');
});

test('triageTicket handles customer not found', async () => {
  const model = scriptedModel([
    {
      toolCalls: [{ name: 'getCustomer', input: { customerId: 'C404' } }],
      usage: [100, 7],
    },
    {
      text: JSON.stringify({
        category: 'other',
        priority: 'normal',
        reply: 'We could not find your account. Please verify your customer ID.',
      }),
      usage: [200, 9],
    },
  ]);

  const result = await triageTicket(model, {
    customerId: 'C404',
    text: 'I cannot access my account',
  });

  assert.equal(result.category, 'other');
  assert.equal(result.priority, 'normal');
  assert.equal(typeof result.reply, 'string');
});

test('triageTicket rejects invalid schema', async () => {
  const model = scriptedModel([
    {
      text: JSON.stringify({
        category: 'invalid',
        priority: 'high',
        reply: 'Invalid category',
      }),
      usage: [100, 7],
    },
  ]);

  await assert.rejects(
    () =>
      triageTicket(model, {
        customerId: 'C1',
        text: 'Some issue',
      }),
    /invalid/i
  );
});

